import { useState, useEffect, useRef } from 'react';
import type { FMItem } from './data/FileManagerData';
import {
    // System
    FILE_SYSTEM,
    LocalDisc,
    MyNetworkPlases,
    RecycleBin,
    RemovableMedia,
    // Personal folders
    MyDocumentsIcon,
    MyPicturesIcon,
    MyMusicIcon,
    MyVideosIcon,
    DesktopIcon,
    DownloadsIcon,
    // Tasks & actions
    ShareFolder,
    NewFolder,
    MoveThisFolder,
    PublishToWeb,
    RestoreAllItems,
    ExploreProperties,
    PlayAll,
    IEMedia,
    Copy,
    CopyToDisc,
    ExplorerDelete,
    Programs,
    Email,
    Rename,
    Camcorder,
    PublishPhotosToWeb,
    Slideshow,
    ControlPanel,
    WindowsUpdate,
    HelpAndSupport,
    PrintPhotos,
    DisplayProperties,
    Search,
    FolderContent
} from './data/FileManagerData';

import MyMusicThumb from '../../img/MyMusic.png'
import MyVideosThumb from '../../img/MyVideos.png'
import MyPicturesThumb from '../../img/MyPictures.png';
import './FileManagerSidebar.css';

interface FileManagerSidebarProps {
    path: string[];
    navigateTo: (newPath: string[]) => void;
    currentNode: FMItem;
    selectedItem: FMItem | null;
    showOtherPlaces: boolean;
    apps: { name: string; size: string }[];
    onControlPanelClassic?: () => void;
    controlPanelClassic?: boolean;
    onSwitchToCategory?: () => void;
    onStartSlideshow?: () => void;
    onDeleteFile?: (item: FMItem) => void;
    onRenameFile?: (item: FMItem) => void;
    onNewFolder?: () => void;
    onRestoreItem?: (item: FMItem) => void;
    onRestoreAll?: () => void;
    onEmptyRecycleBin?: () => void;
    onOpenDisplayProperties?: (tab?: 'Themes' | 'Desktop' | 'Screen Saver' | 'Appearance' | 'Settings') => void;
    onMoveFile?: (item: FMItem) => void;
    onCopyFile?: (item: FMItem) => void;
}

const PERSONAL_SHORTCUTS = [
    { id: 'documents', name: 'My Documents', icon: MyDocumentsIcon, path: ['localdisc', 'c-documents', 'c-admin', 'documents'] },
    { id: 'pictures',  name: 'My Pictures',  icon: MyPicturesIcon,  path: ['localdisc', 'c-documents', 'c-admin', 'pictures'] },
    { id: 'music',     name: 'My Music',     icon: MyMusicIcon,     path: ['localdisc', 'c-documents', 'c-admin', 'music'] },
    { id: 'videos',    name: 'My Videos',    icon: MyVideosIcon,    path: ['localdisc', 'c-documents', 'c-admin', 'videos'] },
    { id: 'downloads', name: 'Downloads',    icon: DownloadsIcon,   path: ['localdisc', 'c-documents', 'c-admin', 'downloads'] },
    { id: 'desktop',   name: 'Desktop',      icon: DesktopIcon,     path: ['localdisc', 'c-documents', 'c-admin', 'desktop'] },
    { id: 'recyclebin', name: 'Recycle Bin', icon: RecycleBin, path: ['recyclebin'] },
];

const FileManagerSidebar = ({ 
    path, 
    navigateTo, 
    currentNode, 
    selectedItem,
    showOtherPlaces,
    apps,
    controlPanelClassic,
    onControlPanelClassic,
    onSwitchToCategory,
    onStartSlideshow,
    onDeleteFile,
    onRenameFile,
    onNewFolder,
    onRestoreItem,
    onRestoreAll,
    onEmptyRecycleBin,
    onOpenDisplayProperties,
    onMoveFile,
    onCopyFile
}: FileManagerSidebarProps) => {
    const [collapsed, setCollapsed] = useState<Record<string, boolean>>({});
    const sidebarRef = useRef<HTMLDivElement>(null);
    const wrapRef = useRef<HTMLDivElement>(null);

    const toggleGroup = (id: string) => {
        setCollapsed(prev => ({ ...prev, [id]: !prev[id] }));
    };

    // Tasks from the Context
        type TaskItem = { icon: string; label: string; onClick?: () => void };

    // File tasks — shown when a file is selected
    const fileTasks: TaskItem[] = [
        { icon: Rename, label: 'Rename this file', onClick: () => { if (selectedItem) onRenameFile?.(selectedItem); } },
        { icon: MoveThisFolder, label: 'Move this file', onClick: () => { if (selectedItem) onMoveFile?.(selectedItem); } },
        { icon: Copy, label: 'Copy this file', onClick: () => { if (selectedItem) onCopyFile?.(selectedItem); } },
        { icon: PublishToWeb, label: 'Publish this file to the Web' },
        { icon: Email, label: 'E-mail this file' },
        { icon: ExplorerDelete, label: 'Delete this file', onClick: () => { if (selectedItem) onDeleteFile?.(selectedItem); } },
    ];

    // Folder tasks — shown when no file is selected
    const folderTaskItems: TaskItem[] = [
        { icon: NewFolder, label: 'Make a new folder', onClick: onNewFolder },
        { icon: PublishToWeb, label: 'Publish this folder to the Web' },
        { icon: ShareFolder, label: 'Share this folder' },
    ];

    const folderSelectedTasks: TaskItem[] = [
        { icon: Rename, label: 'Rename this folder', onClick: () => { if (selectedItem) onRenameFile?.(selectedItem); } },
        { icon: MoveThisFolder, label: 'Move this folder', onClick: () => { if (selectedItem) onMoveFile?.(selectedItem); } },
        { icon: Copy, label: 'Copy this folder', onClick: () => { if (selectedItem) onCopyFile?.(selectedItem); } },
        { icon: PublishToWeb, label: 'Publish this folder to the Web' },
        { icon: ShareFolder, label: 'Share this folder' },
        { icon: Email, label: "E-mail this folder's files" },
        { icon: ExplorerDelete, label: 'Delete this folder', onClick: () => { if (selectedItem) onDeleteFile?.(selectedItem); } },
    ];

    const SPECIAL_ICONS: Record<string, string> = {
        music: MyMusicThumb,
        pictures: MyPicturesThumb,
        video: MyVideosThumb,
        documents: MyDocumentsIcon,
    };

    // Context-aware task groups
    const getTasks = () => {
        const secondaryTasks = !selectedItem
        ? folderTaskItems
        : selectedItem.type === 'file'
            ? fileTasks
            : folderSelectedTasks;

        // System tasks
        if (currentNode.id === 'root') {
            return {
                title: 'System Tasks',
                items: [
                    { icon: ExploreProperties, label: 'View system information' },
                    { icon: Programs, label: 'Add or remove programs' },
                    { icon: ControlPanel, label: 'Change a setting' },
                ],
                folderTasks: null,
            };
        }
        // Music tasks
        if (currentNode.id === 'music') {
            return {
                title: 'Music Tasks',
                items: [
                    { icon: PlayAll, label: 'Play all' },
                    { icon: IEMedia, label: 'Shop for music online' },
                    { icon: CopyToDisc, label: 'Copy all items to audio CD' },
                ],
                folderTasks: secondaryTasks,
            };
        }
        // Video Tasks
        if (currentNode.id === 'videos') {
            return {
                title: 'Video Tasks',
                items: [
                    { icon: PlayAll, label: 'Play all' },
                    { icon: CopyToDisc, label: 'Copy to CD' },
                    { icon: Camcorder, label: 'Get videos from camera or scanner' },
                    { icon: IEMedia, label: 'Shop for videos online' },
                ],
                folderTasks: secondaryTasks,
            };
        }
        // Picture Tasks
        if (currentNode.id === 'pictures') {
            return {
                title: 'Picture Tasks',
                items: selectedItem?.type === 'file' ? [
                    { icon: Slideshow, label: 'View as a slide show', onClick: onStartSlideshow },
                    { icon: PublishPhotosToWeb, label: 'Order prints online' },
                    { icon: PrintPhotos, label: 'Print this picture' },
                    { icon: DisplayProperties, label: 'Set as desktop background', onClick: () => onOpenDisplayProperties?.('Desktop') },
                ] : [
                    { icon: Slideshow, label: 'View as a slide show', onClick: onStartSlideshow },
                    { icon: PublishPhotosToWeb, label: 'Order prints online' },
                    { icon: PrintPhotos, label: 'Print pictures' },
                    { icon: CopyToDisc, label: 'Copy all items to CD' },
                ],
                folderTasks: secondaryTasks,
            };
        }
        
        // Reccycle Bin tasks
        if (currentNode.id === 'recyclebin') {
            return {
                title: 'Recycle Bin Tasks',
                items: [
                    { icon: RecycleBin, label: 'Empty the Recycle Bin', onClick: onEmptyRecycleBin },
                    selectedItem
                        ? { icon: RestoreAllItems, label: 'Restore this item', onClick: () => onRestoreItem?.(selectedItem) }
                        : { icon: RestoreAllItems, label: 'Restore all items', onClick: onRestoreAll },
                ],
                folderTasks: null,
            };
        }

        if (currentNode.id === 'desktop') {
            return {
                title: 'File and Folder Tasks',
                items: [
                    { icon: PublishToWeb, label: 'Publish the selected items to the Web' },
                    { icon: Email, label: 'E-mail the selected items' },
                    { icon: ExplorerDelete, label: 'Delete the selected items' },
                ],
                folderTasks: null,
            };
        }
        if (currentNode.id === 'controlpanel') {
            return {
                title: 'Control Panel',
                items: controlPanelClassic
                    ? [{ icon: ControlPanel, label: 'Switch to Category View', onClick: onSwitchToCategory }]
                    : [{ icon: ControlPanel, label: 'Switch to Classic View', onClick: onControlPanelClassic }],
                folderTasks: null,
            };
        }
        if (currentNode.id.startsWith('cp-')) {
            return {
                title: 'Control Panel',
                items: [
                    { icon: ControlPanel, label: 'Control Panel Home', onClick: () => navigateTo(['controlpanel']) },
                    { icon: ControlPanel, label: 'Switch to Classic View', onClick: onControlPanelClassic },
                ],
                folderTasks: null,
            };
        }

        if (currentNode.id === 'c-windows') {
            return {
                title: 'System Tasks',
                items: [
                    { icon: FolderContent, label: 'Hide the contents of this folder' },
                    { icon: Programs, label: 'Add or remove programs' },
                    { icon: Search, label: 'Search for files or folders' },
                ],
                folderTasks: secondaryTasks,
            };
        }

        // Basic tasks
        return {
            title: 'File and Folder Tasks',
            items: secondaryTasks,
            folderTasks: null,
        };
    };

    const tasks = getTasks();

    const isSpecialBox =
        !currentNode.id.startsWith('cp-') &&
        currentNode.id !== 'controlpanel' &&
        tasks.title !== 'File and Folder Tasks';

    const updateSidebarArrows = () => {
        const sidebar = sidebarRef.current;
        const wrap = wrapRef.current;
        if (!sidebar || !wrap) return;
        const isScrollable = sidebar.scrollHeight > sidebar.clientHeight;
        wrap.classList.toggle('show-top-arrow', isScrollable);
        wrap.classList.toggle('show-bottom-arrow', isScrollable);
    };

    useEffect(() => {
        setTimeout(updateSidebarArrows, 0);
        const sidebar = sidebarRef.current;
        if (!sidebar) return;
        sidebar.addEventListener('scroll', updateSidebarArrows);
        window.addEventListener('resize', updateSidebarArrows);
        return () => {
            sidebar.removeEventListener('scroll', updateSidebarArrows);
            window.removeEventListener('resize', updateSidebarArrows);
        };
    }, [collapsed]);

    // Other Places — context-aware shortcuts
    const getOtherPlaces = () => {
        if (currentNode.id === 'root') {
            return [
                { id: 'network', name: 'My Network Places', icon: MyNetworkPlases, path: [] },
                { id: 'documents', name: 'My Documents', icon: MyDocumentsIcon, path: ['localdisc', 'c-documents', 'c-admin', 'documents'] },
                { id: 'localdisc', name: 'Local Disk (C:)', icon: LocalDisc, path: ['localdisc'] },
                { id: 'controlpanel', name: 'Control Panel', icon: ControlPanel, path: ['controlpanel'] },
            ];
        }
        if (currentNode.id === 'music') {
            return [
                { id: 'documents', name: 'My Documents', icon: MyDocumentsIcon, path: ['localdisc', 'c-documents', 'c-admin', 'documents'] },
                { id: 'music', name: 'My Music', icon: MyMusicIcon, path: ['localdisc', 'c-documents', 'c-admin', 'music'] },
                { id: 'root', name: 'My Computer', icon: FILE_SYSTEM.icon, path: [] },
                { id: 'network', name: 'My Network Places', icon: MyNetworkPlases, path: [] },
            ];
        }
        if (currentNode.id === 'pictures') {
            return [
                { id: 'documents', name: 'My Documents', icon: MyDocumentsIcon, path: ['localdisc', 'c-documents', 'c-admin', 'documents'] },
                { id: 'pictures', name: 'My Pictures', icon: MyPicturesIcon, path: ['localdisc', 'c-documents', 'c-admin', 'pictures'] },
                { id: 'root', name: 'My Computer', icon: FILE_SYSTEM.icon, path: [] },
                { id: 'network', name: 'My Network Places', icon: MyNetworkPlases, path: [] },
            ];
        }
        if (currentNode.id === 'videos') {
            return [
                { id: 'documents', name: 'My Documents', icon: MyDocumentsIcon, path: ['localdisc', 'c-documents', 'c-admin', 'documents'] },
                { id: 'videos', name: 'My Videos', icon: MyVideosIcon, path: ['localdisc', 'c-documents', 'c-admin', 'videos'] },
                { id: 'shared-videos', name: 'Shared Videos', icon: MyVideosIcon, path: ['localdisc', 'c-documents', 'shared-videos'] },
                { id: 'root', name: 'My Computer', icon: FILE_SYSTEM.icon, path: [] },
                { id: 'network', name: 'My Network Places', icon: MyNetworkPlases, path: [] },
            ];
        }
        if (currentNode.id === 'downloads') {
            return [
                { id: 'documents', name: 'My Documents', icon: MyDocumentsIcon, path: ['localdisc', 'c-documents', 'c-admin', 'documents'] },
                { id: 'root', name: 'My Computer', icon: FILE_SYSTEM.icon, path: [] },
                { id: 'network', name: 'My Network Places', icon: MyNetworkPlases, path: [] },
            ];
        }

        if (currentNode.id === 'documents') {
            return [
                { id: 'root', name: 'My Computer', icon: FILE_SYSTEM.icon, path: [] },
                { id: 'network', name: 'My Network Places', icon: MyNetworkPlases, path: [] },
            ];
        }

        if (currentNode.id === 'desktop') {
            return [
                { id: 'documents', name: 'My Documents', icon: MyDocumentsIcon, path: ['localdisc', 'c-documents', 'c-admin', 'documents'] },
                { id: 'root', name: 'My Computer', icon: FILE_SYSTEM.icon, path: [] },
                { id: 'network', name: 'My Network Places', icon: MyNetworkPlases, path: [] },
            ];
        }

        if (currentNode.id === 'recyclebin') {
            return [
                { id: 'localdisc', name: 'Local Disk (C:)', icon: LocalDisc, path: ['localdisc'] },
                { id: 'cdrom', name: 'CD Drive (D:)', icon: RemovableMedia, path: ['cdrom'] },
                { id: 'recyclebin', name: 'Recycle Bin', icon: RecycleBin, path: ['recyclebin'] },
            ];
        }

        if (currentNode.id === 'c-windows') {
            return [
                { id: 'localdisc', name: 'Local Disk (C:)', icon: LocalDisc, path: ['localdisc'] },
                { id: 'documents', name: 'My Documents', icon: MyDocumentsIcon, path: ['localdisc', 'c-documents', 'c-admin', 'documents'] },
                { id: 'shareddocs', name: 'Shared Documents', icon: MyDocumentsIcon, path: ['localdisc', 'c-documents', 'shared-docs'] },
                { id: 'root', name: 'My Computer', icon: FILE_SYSTEM.icon, path: [] },
            ];
        }

        return PERSONAL_SHORTCUTS;
    };

    const otherPlaces = getOtherPlaces();

    // Details panel — selected item or current folder
    // FilE Size
    const getSize = () => {
        if (detailsItem.name.endsWith('.lnk')) {
            const nameMap: Record<string, string> = {
                'Terminal': 'Command Prompt',
                'My Files': 'File Manager',
                'My Computer': 'File Manager',
            };
            const appName = detailsItem.name.replace('.lnk', '');
            const mappedName = nameMap[appName] ?? appName;
            const app = apps.find(a => a.name === mappedName);
            return app ? app.size + ' KB' : detailsItem.size;
        }
        return detailsItem.size;
    };

    const detailsItem = selectedItem ?? currentNode;
    const SYSTEM_FOLDER_IDS = new Set(['root', 'recyclebin', 'controlpanel', 'network']);
    const DRIVE_TYPES: Record<string, string> = {
        floppyA: '3½ Inch Floppy Disk',
        floppyB: '3½ Inch Floppy Disk',
        localdisc: 'Local Disk',
        cdrom: 'Local Disk',
        cdrw: 'CD Drive',
    };
    const getDetailsType = () => {
        if (!selectedItem && SYSTEM_FOLDER_IDS.has(currentNode.id)) return 'System Folder';
        if (DRIVE_TYPES[detailsItem.id]) return DRIVE_TYPES[detailsItem.id];
        if (detailsItem.type === 'folder') return 'File Folder';
        return (detailsItem.name.split('.').pop()?.toUpperCase() ?? 'File') + ' File';
    };
    const detailsType = getDetailsType();

    const activeFolderType = (() => {
        let node = FILE_SYSTEM;
        let found = node.folderType;
        for (const id of path) {
            const child = node.children?.find(c => c.id === id);
            if (!child) break;
            node = child;
            if (node.folderType) found = node.folderType;
        }
        return found;
    })();

    return (
        <div ref={wrapRef} className='fm-sidebar-wrap'>
            <div ref={sidebarRef} className='fm-sidebar'>

               {/* Tasks */}
                {!currentNode.id.startsWith('cp-') && <div
                    className='fm-task-group'
                    data-folder-type={activeFolderType}
                    data-cp-category={currentNode.id === 'controlpanel' ? 'true' : undefined}
                    data-cp-classic={undefined}
                    data-special-box={isSpecialBox ? 'true' : undefined}
                >
                    <div className='fm-task-header' onClick={() => toggleGroup('tasks')}>
                        {currentNode.id === 'controlpanel' && (
                            <img src={ControlPanel} alt='' className='fm-task-icon' />
                        )}
                        {isSpecialBox && activeFolderType && SPECIAL_ICONS[activeFolderType] && (
                            <img src={SPECIAL_ICONS[activeFolderType]} alt='' className='fm-task-icon' />
                        )}
                        <span>{tasks.title}</span>
                        <span className='fm-task-chevron'>{collapsed['tasks'] ? '»' : '«'}</span>
                    </div>
                    {!collapsed['tasks'] && (
                        <div className='fm-task-body'>
                            {tasks.items.map((item, index) => (
                                <button 
                                    key={index} 
                                    type='button' 
                                    className='fm-task-link' 
                                    onClick={'onClick' in item ? item.onClick : undefined}
                                >
                                    <img src={item.icon} alt='' className='fm-task-icon' />
                                    {item.label}
                                </button>
                            ))}
                        </div>
                    )}
                </div>}

                                {/* File and Folder Tasks */}
                {tasks.folderTasks && (
                    <div className='fm-task-group'>
                        <div className='fm-task-header' onClick={() => toggleGroup('foldertasks')}>
                            <span>File and Folder Tasks</span>
                            <span className='fm-task-chevron'>{collapsed['foldertasks'] ? '»' : '«'}</span>
                        </div>
                        {!collapsed['foldertasks'] && (
                            <div className='fm-task-body'>
                                {tasks.folderTasks.map((item, index) => (
                                    <button key={index} type='button' className='fm-task-link' onClick={item.onClick}>
                                        <img src={item.icon} alt='' className='fm-task-icon' />
                                        {item.label}
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {/* Other Places / See Also */}
                {showOtherPlaces && (
                    <div className='fm-task-group'>
                        <div className='fm-task-header' onClick={() => toggleGroup('places')}>
                            <span>{(currentNode.id === 'controlpanel' || currentNode.id.startsWith('cp-')) && !controlPanelClassic ? 'See Also' : 'Other Places'}</span>
                            <span className='fm-task-chevron'>{collapsed['places'] ? '»' : '«'}</span>
                        </div>
                        {!collapsed['places'] && (
                            <div className='fm-task-body'>
                                {(currentNode.id === 'controlpanel' || currentNode.id.startsWith('cp-')) && !controlPanelClassic ? (
                                    <>
                                        <button type='button' className='fm-task-link'>
                                            <img src={WindowsUpdate} alt='' className='fm-task-icon' />
                                            Windows Update
                                        </button>
                                        <button type='button' className='fm-task-link'>
                                            <img src={HelpAndSupport} alt='' className='fm-task-icon' />
                                            Help and Support
                                        </button>
                                    </>
                                ) : (
                                    otherPlaces.map(place => (
                                        <button
                                            key={place.id}
                                            type='button'
                                            className={`fm-task-link${path.join('/') === place.path.join('/') ? ' active' : ''}`}
                                            onClick={() => navigateTo(place.path)}
                                        >
                                            <img src={place.icon} alt='' className='fm-task-icon' />
                                            {place.name}
                                        </button>
                                    ))
                                )}
                            </div>
                        )}
                    </div>
                )}

                {/* Details  */}
                {!(currentNode.id === 'controlpanel' && !controlPanelClassic) && !currentNode.id.startsWith('cp-') && (
                    <div className='fm-task-group'>
                        <div className='fm-task-header' onClick={() => toggleGroup('details')}>
                            <span>Details</span>
                            <span className='fm-task-chevron'>{collapsed['details'] ? '»' : '«'}</span>
                        </div>
                        {!collapsed['details'] && (
                            <div className='fm-task-body fm-task-details'>
                                <img src={detailsItem.icon} alt='' className='fm-details-icon' />
                                <div className='fm-details-name'>{detailsItem.name}</div>
                                <div className='fm-details-type'>{detailsType}</div>
                                {detailsItem.size && (
                                    <div className='fm-details-date'>Size: {getSize()}</div>
                                )}
                                {detailsItem.modified && (
                                    <div className='fm-details-date'>Date: {detailsItem.modified}</div>
                                )}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

export default FileManagerSidebar;