import { useState, useEffect, useRef, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { FILE_SYSTEM, getDesktopItems } from './data/FileManagerData';
import ControlPanelIcon from '../../img/ControlPanel.webp';
import type { FMItem } from './data/FileManagerData';
import type { WMPTrack } from '../mediaPlayer/types/WMPTrack';
import { addRecentDoc } from '../../utils/recentDocs';
import { useFileSystem } from '../../hooks/fileSystemContext';
import useSound from '../../hooks/useSound';
import { getRootCategoryIndex, groupRootItems } from './data/rootCategories';
import CriticalError from '../CriticalError';

import FileManagerSidebar from './FileManagerSidebar';
import HistorySidebar from './HistorySidebar';
import SearchSidebar from './rover/SearchSidebar';
import TipOfTheDay from './TipOfTheDay';
import PictureViewer from './PictureViewer';
import HiddenFolderWarning from './HiddenFolderWarning';
import ControlPanelHome from './controlPanel/ControlPanelHome';
import ControlPanelAppearance from './controlPanel/ControlPanelAppearance';
import ControlPanelNetwork from './controlPanel/ControlPanelNetwork';
import ControlPanelPrinters from './controlPanel/ControlPanelPrinters';
import ControlPanelDate from './controlPanel/ControlPanelDate';
import ControlPanelAccessibility from './controlPanel/ControlPanelAccessibility';
import ControlPanelAccounts from './controlPanel/ControlPanelAccounts';
import ControlPanelSound from './controlPanel/ControlPanelSound';
import ControlPanelPerformance from './controlPanel/ControlPanelPerformance';
import MoveCopyDialog from './MoveCopyDialog';

import { FolderClosedIcon } from './data/icons';
import Forward from '../../img/Forward.webp';
import Back from '../../img/Back.webp';
import Up from '../../img/Up.webp';
import Search from '../../img/Search.webp';
import Folders from '../../img/FolderView.webp';
import Go from '../../img/Go.webp';

//View
// import Default from '../../img/FolderViewClassic.webp';
import ThumbnailView from '../../img/ThumbnailView.webp';
import DetailView from '../../img/DetailView.webp';
import TileView from '../../img/TileView.webp';
import IconView from '../../img/IconView.webp';
import ListView from '../../img/OEFolderList.webp';
import FontSimilarityView from '../../img/FontSimilarityView.webp'

import XPScrollbar from '../XPScrollbar';
import './FileManagerApp.css';

interface FileManagerAppProps {
    onFolderChange: (name: string, icon: string | undefined, id?: string) => void;
    initialPath?: string[];
    onOpenApp: (id: string) => void;
    pathKey: number;
    viewMode: 'thumbnails' | 'tiles' | 'icons' | 'list' | 'details' | 'similarity' | 'filmstrip';
    onViewChange: (mode: 'thumbnails' | 'tiles' | 'icons' | 'list' | 'details' | 'similarity' | 'filmstrip') => void;
    onNavigationChange?: (
        canGoBack: boolean, 
        canGoForward: boolean, 
        canGoUp: boolean, 
        goBack: () => void, 
        goForward: () => void, 
        goUp: () => void
    ) => void;
    showStatusBar: boolean;
    sortBy: 'name' | 'size' | 'type' | 'modified';
    showStandardButtons: boolean;
    showAddressBar: boolean;
    showOtherPlaces: boolean;
    showTipOfTheDay: boolean;
    onCloseTipOfTheDay: () => void;
    showHistory: boolean;
    onCloseHistory: () => void;
    showSearch: boolean;
    onCloseSearch: () => void;
    onToggleSearch: () => void;
    apps: { name: string; size: string }[];
    onOpenNotepad?: (content: string, fileName: string) => void;
    onOpenWMP?: (tracks: WMPTrack[], startIndex: number) => void;
    onOpenIE?: (url?: string) => void;
    onOpenFontView?: (item: FMItem) => void;
    globalVolume: number;
    globalMuted: boolean;
    pickerMode?: 'wallpaper' | 'object' | 'audio' | null;
    onFilePicked?: (url: string) => void;
    onObjectPicked?: (item: FMItem) => void;
    onOpenDisplayProperties?: (tab?: 'Themes' | 'Desktop' | 'Screen Saver' | 'Appearance' | 'Settings') => void;
    onOpenVolumeControl?: () => void;
    onOpenPictureFax?: (item: FMItem, images?: FMItem[], slideshow?: boolean) => void;
    onSelectionChange?: (
        item: FMItem | null,
        onDelete: (item: FMItem) => void,
        onRename: (item: FMItem) => void,
        onMove: (item: FMItem) => void,
        onCopy: (item: FMItem) => void,
        onSendTo: (item: FMItem, targetId: string) => void
    ) => void;
    onNewFolderReady?: (onNewFolder: () => void) => void;
}

// File extensions accepted by the wallpaper picker. .jpeg covered by suffix match.
const IMAGE_EXTS = ['.webp', '.jpg', '.jpeg', '.png', '.bmp', '.gif'] as const;
const isPickableImage = (item: FMItem): string | null => {
    const lower = item.name.toLowerCase();
    if (!IMAGE_EXTS.some(ext => lower.endsWith(ext))) return null;
    return item.imageUrl ?? item.thumbnailUrl ?? null;
};

const getFolderIcon = (node: { id: string; icon?: string }) =>
    node.id.startsWith('cp-') ? ControlPanelIcon : node.icon;

const generateId = (prefix: string) =>
    `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;

const FileManagerApp = ({ 
    onFolderChange, 
    initialPath, 
    onOpenApp, 
    pathKey,
    viewMode,
    onViewChange, 
    onNavigationChange,
    showStatusBar,
    sortBy,
    showStandardButtons,
    showAddressBar,
    showOtherPlaces,
    showTipOfTheDay,
    onCloseTipOfTheDay,
     showHistory,
     onCloseHistory,
     showSearch,
     onCloseSearch,
     onToggleSearch,
     apps,
     onOpenNotepad,
     onOpenIE,
     onOpenWMP,
     onOpenFontView,
     globalVolume,
     globalMuted,
     pickerMode,
     onFilePicked,
     onObjectPicked,
     onOpenDisplayProperties,
     onOpenVolumeControl,
     onOpenPictureFax,
     onSelectionChange,
     onNewFolderReady
}: FileManagerAppProps) => {
    const [path, setPath] = useState<string[]>(initialPath ?? []);
    const [navHistory, setNavHistory] = useState<string[][]>([initialPath ?? []]);
    const [historyIndex, setHistoryIndex] = useState(0);
    const [viewDropdownOpen, setViewDropdownOpen] = useState(false);
    const [selectedId, setSelectedId] = useState<string | null>(null);
    const [viewerImageId, setViewerImageId] = useState<string | null>(null);
    const [revealedHidden, setRevealedHidden] = useState<Set<string>>(new Set());
    const [searchResults, setSearchResults] = useState<FMItem[] | null>(null);
    const [controlPanelClassic, setControlPanelClassic] = useState(false);
    const [similarityBaseFont, setSimilarityBaseFont] = useState('Arial');
    const [pendingDelete, setPendingDelete] = useState<FMItem | null>(null);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editingName, setEditingName] = useState('');
    const [moveCopyTarget, setMoveCopyTarget] = useState<{ item: FMItem; mode: 'move' | 'copy' } | null>(null);

    const { 
        getExtraChildren, 
        isDeleted, 
        applyOverlay, 
        deleteFile, 
        getRecycleBinItems, 
        restoreFile, 
        emptyRecycleBin, 
        renameFile, 
        createFile, 
        permanentlyDeleteFile,
        moveFile,
    } = useFileSystem();
    const { playStart } = useSound(globalVolume, globalMuted);

    const handleViewerChange = (id: string) => {
        setViewerImageId(id);
        setSelectedId(id);
        const item = sortedChildren.find(c => c.id === id);
        if (item) {
            addRecentDoc({ name: item.name, path: item.id, type: 'image' });
        }
    };

    const handleDeleteFile = (item: FMItem) => {
        setPendingDelete(item);
    };

    const confirmDelete = () => {
        if (pendingDelete) {
            if (currentNode.id === 'recyclebin') {
                permanentlyDeleteFile(pendingDelete.id);
            } else {
                deleteFile(pendingDelete.id, pendingDelete, currentNode.id);
            }
            if (selectedId === pendingDelete.id) setSelectedId(null);
        }
        setPendingDelete(null);
    };

     const handleRestoreItem = (item: FMItem) => {
        restoreFile(item.id);
        setSelectedId(null);
    };

    const handleRestoreAll = () => {
        getRecycleBinItems().forEach(item => restoreFile(item.id));
        setSelectedId(null);
    };

    const handleEmptyRecycleBin = () => {
        emptyRecycleBin();
        setSelectedId(null);
    };

    const handleNewFolder = () => {
        const existingNames = new Set((currentChildren ?? []).map(c => c.name));
        let name = 'New Folder';
        if (existingNames.has(name)) {
            let n = 1;
            while (existingNames.has(`New Folder (${n})`)) n++;
            name = `New Folder (${n})`;
        }
        const newId = generateId('folder');
        const newFolder: FMItem = {
            id: newId,
            type: 'folder',
            name,
            icon: FolderClosedIcon,
            children: [],
        };
        createFile(currentNode.id, newFolder);
        setEditingId(newId);
        setEditingName(name);
    };

    const handleRenameFile = (item: FMItem) => {
        setEditingId(item.id);
        setEditingName(item.name);
    };

    const commitRename = () => {
        if (editingId && editingName.trim()) {
            renameFile(editingId, editingName.trim());
        }
        setEditingId(null);
    };

    const cancelRename = () => {
        setEditingId(null);
    };

    const handleMoveFile = (item: FMItem) => {
        setMoveCopyTarget({ item, mode: 'move' });
    };

    const handleCopyFile = (item: FMItem) => {
        setMoveCopyTarget({ item, mode: 'copy' });
    };

    const confirmMoveCopy = (targetParentId: string) => {
        if (!moveCopyTarget) return;
        const { item, mode } = moveCopyTarget;
        if (mode === 'move') {
            moveFile(item.id, item, currentNode.id, targetParentId);
            setSelectedId(null);
        } else {
            createFile(targetParentId, { ...item, id: generateId(`${item.id}-copy`) });
        }
        setMoveCopyTarget(null);
    };

    const handleSendToFolder = (item: FMItem, targetId: string) => {
        const findNode = (node: FMItem, id: string): FMItem | null => {
            if (node.id === id) return node;
            for (const child of [...(node.children ?? []), ...getExtraChildren(node.id)]) {
                const found = findNode(child, id);
                if (found) return found;
            }
            return null;
        };
        const targetNode = findNode(FILE_SYSTEM, targetId);
        const existingNames = new Set([
            ...(targetNode?.children ?? []),
            ...getExtraChildren(targetId),
        ]
            .filter(c => !isDeleted(c.id))
            .map(c => c.name));

        let name = item.name;
        if (existingNames.has(name)) {
            let n = 1;
            while (existingNames.has(`${item.name} (${n})`)) n++;
            name = `${item.name} (${n})`;
        }

        createFile(targetId, { ...item, id: generateId(`${item.id}-sendto`), name });
    };

    // FOLDER NAVIGATION
    const navigateTo = (newPath: string[]) => {
        setViewerImageId(null);
        setSearchResults(null);
        setPath(newPath);
        const trimmed = navHistory.slice(0, historyIndex + 1);
        const newHistory = [...trimmed, newPath];
        setNavHistory(newHistory);
        setHistoryIndex(trimmed.length);
        const node = getNodeAtPath(newPath);
        onFolderChange(node.name, getFolderIcon(node), node.id);
        playStart();
    };

    const goBack = () => {
        if (historyIndex === 0) return;
        setViewerImageId(null);
        const newIndex = historyIndex - 1;
        setHistoryIndex(newIndex);
        setPath(navHistory[newIndex]);
        const node = getNodeAtPath(navHistory[newIndex]);
        onFolderChange(node.name, getFolderIcon(node), node.id);
        playStart();
    };

    const goForward = () => {
        if (historyIndex === navHistory.length - 1) return;
        setViewerImageId(null);
        const newIndex = historyIndex + 1;
        setHistoryIndex(newIndex);
        setPath(navHistory[newIndex]);
        const node = getNodeAtPath(navHistory[newIndex]);
        onFolderChange(node.name, getFolderIcon(node), node.id);
        playStart();
    };

    const goUp = () => {
        if (path.length === 0) return;
        navigateTo(path.slice(0, -1));
    };

    // Refs to always have latest version of nav functions
    const goBackRef = useRef(goBack);
    const goForwardRef = useRef(goForward);
    const goUpRef = useRef(goUp);

    useEffect(() => {
        goBackRef.current = goBack;
        goForwardRef.current = goForward;
        goUpRef.current = goUp;
    });

    const updateNav = (histIdx: number, histLen: number, pathLen: number) => {
        onNavigationChange?.(
            histIdx > 0,
            histIdx < histLen - 1,
            pathLen > 0,
            () => goBackRef.current(),
            () => goForwardRef.current(),
            () => goUpRef.current()
        );
    };

    const getNodeAtPath = (path: string[]): FMItem => {
        if (!path || !Array.isArray(path)) return FILE_SYSTEM;
        let node = FILE_SYSTEM;
        for (const id of path) {
            const child = node.children?.find(c => c.id === id) ?? getExtraChildren(node.id).find(c => c.id === id);
            if (!child) break;
            node = child;
        }
        return node;
    };

    const isFirstRender = useRef(true);

    useEffect(() => {
        const node = getNodeAtPath(path);
        onFolderChange(node.name, getFolderIcon(node), node.id);
        updateNav(historyIndex, navHistory.length, path.length);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    useEffect(() => {
        updateNav(historyIndex, navHistory.length, path.length);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [historyIndex, navHistory, path]);

    // Clear stale search results when the Search panel is closed
    useEffect(() => {
        if (!showSearch) setSearchResults(null);
    }, [showSearch]);

    // XP-authentic: My Pictures defaults to Filmstrip view. Reverts to Thumbnails when
    // navigating out so filmstrip doesn't bleed into folders without images.
    const currentFolderId = path[path.length - 1];
    useEffect(() => {
        if (currentFolderId === 'pictures') {
            onViewChange('filmstrip');
        } else if (viewMode === 'filmstrip') {
            onViewChange('thumbnails');
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [currentFolderId]);

    useEffect(() => {
        if (isFirstRender.current) {
            isFirstRender.current = false;
            return;
        }
        const newPath = initialPath ?? [];
        const node = getNodeAtPath(newPath);
        setPath(newPath);
        setNavHistory([newPath]);
        setHistoryIndex(0);
        onFolderChange(node.name, getFolderIcon(node), node.id);
        updateNav(0, 1, newPath.length);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [pathKey]);

    const canGoBack = historyIndex > 0;
    const canGoForward = historyIndex < navHistory.length - 1;
    const canGoUp = path.length > 0;
    const currentNode = getNodeAtPath(path);

    // DATA DERIVED FROM PATH
    const isDesktop = path[path.length - 1] === 'desktop';
    const currentChildren = (showSearch && searchResults)
        ? searchResults
        : currentNode.id === 'recyclebin'
            ? getRecycleBinItems()
            : isDesktop
                ? getDesktopItems(apps)
                : [...(currentNode.children ?? []), ...getExtraChildren(currentNode.id)]
                    .filter(item => !isDeleted(item.id))
                    .map(applyOverlay);

    const sortedChildren = [...(currentChildren ?? [])].sort((a, b) => {
        if (currentNode.id === 'root' && sortBy === 'name') {
            const catA = getRootCategoryIndex(a.id);
            const catB = getRootCategoryIndex(b.id);
            if (catA !== catB) return catA - catB;
            return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
        }
        if (a.type !== b.type) return a.type === 'folder' ? -1 : 1;
        if (sortBy === 'name') {
            return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
        }
         if (sortBy === 'type') {
            const extA = a.name.split('.').pop()?.toLowerCase() ?? '';
            const extB = b.name.split('.').pop()?.toLowerCase() ?? '';
            return extA.localeCompare(extB);
        }
        if (sortBy === 'modified') {
            const parseDate = (d?: string) => {
                if (!d) return 0;
                const [day, month, year] = d.split('/').map(Number);
                return new Date(year, month - 1, day).getTime();
            };
            return parseDate(a.modified) - parseDate(b.modified);
        }
        if (sortBy === 'size') {
            const parseSize = (s?: string) => {
                if (!s) return 0;
                return parseInt(s.replace(/,/g, '').replace(' KB', ''));
            };
            return parseSize(a.size) - parseSize(b.size);
        }
        return 0; // PLACEHOLDER - ORTING IS IN DEVELOPEMNT
    });

    const rootGroups = currentNode.id === 'root' && viewMode !== 'list'
        ? groupRootItems(sortedChildren)
        : null;

    useEffect(() => {
        const item = sortedChildren?.find(c => c.id === selectedId) ?? null;
        onSelectionChange?.(item, handleDeleteFile, handleRenameFile, handleMoveFile, handleCopyFile, handleSendToFolder);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [selectedId, sortedChildren]);

    useEffect(() => {
        onNewFolderReady?.(handleNewFolder);
    });

    const breadcrumbs = useMemo(() => {
        const crumbs = [{ name: 'My Computer', icon: FILE_SYSTEM.icon }];
        if (!path || !Array.isArray(path)) return crumbs;
        let node = FILE_SYSTEM;
        for (const id of path) {
            const child = node.children?.find(c => c.id === id);
            if (!child) break;
            crumbs.push({ name: child.name, icon: child.icon });
            node = child;
        }
        return crumbs;
    }, [path]);


    // KEYBOARD SHORTCUTS
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            // Don't hijack keys while the user is typing into an editable field
            const target = e.target as HTMLElement | null;
            if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable)) {
                return;
            }
            if (e.key === 'Backspace') {
                e.preventDefault();
                goUpRef.current();
            }
             if (e.key === 'Delete' && selectedId !== null) {
                e.preventDefault();
                const item = sortedChildren.find(c => c.id === selectedId);
                if (item) handleDeleteFile(item);
            }
            if (e.key === 'F2' && selectedId !== null) {
                e.preventDefault();
                const item = sortedChildren.find(c => c.id === selectedId);
                if (item) handleRenameFile(item);
            }
            if (e.altKey && e.key === 'ArrowLeft') {
                e.preventDefault();
                goBackRef.current();
            }
            if (e.altKey && e.key === 'ArrowRight') {
                e.preventDefault();
                goForwardRef.current();
            }
            if (e.key === 'Enter' && selectedId !== null) {
                const item = sortedChildren.find(c => c.id === selectedId);
                if (item) {
                    if (pickerMode === 'object' && item.type !== 'folder') {
                        onObjectPicked?.(item);
                        return;
                    }
                    if (pickerMode === 'audio' && item.type !== 'folder') {
                        if ((item.name.endsWith('.mp3') || item.name.endsWith('.wav') || item.name.endsWith('.webm')) && item.trackData?.url) {
                            onFilePicked?.(item.trackData.url);
                        }
                        return;
                    }
                    if (item.id === 'cp-fonts') {
                            navigateTo(['localdisc', 'c-windows', 'c-windows-fonts']);
                            return;
                        }
                    if (item.id === 'cp-display') {
                        onOpenDisplayProperties?.();
                        return;
                    }
                    if (item.id === 'pfie-iexplore') {
                        onOpenIE?.();
                        return;
                    }
                    if (item.type === 'folder') {
                        navigateTo([...path, item.id]);
                    } else if (item.name.endsWith('.lnk')) {
                        onOpenApp(item.id);
                        setSelectedId(null);
                    } else if (item.name.endsWith('.txt') || item.name.endsWith('.md')) {
                        openNotepad(item);
                    } else if (item.name.endsWith('.html') || item.name.endsWith('.htm')) {
                        openHtmlPage(item);
                    } else if (item.url) {
                        onOpenIE?.(item.url);
                    }
                    else if (item.name.endsWith('.mp3') || item.name.endsWith('.wav') || item.name.endsWith('.webm')) {
                        openWMP(item);
                    }
                    else if (item.fontUrl) {
                        onOpenFontView?.(item);
                    }
                }
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [selectedId, sortedChildren, path]);

    const openPictureFax = (item: FMItem) => {
        const siblings = sortedChildren.filter(c => (c.thumbnailUrl || c.imageUrl) && c.type === 'file');
        onOpenPictureFax?.(item, siblings.length > 0 ? siblings : [item]);
    };

    const startSlideshow = () => {
        const pictures = sortedChildren.filter(c => (c.thumbnailUrl || c.imageUrl) && c.type === 'file');
        if (pictures.length === 0) return;
        const selected = sortedChildren.find(c => c.id === selectedId);
        const start = selected && pictures.some(p => p.id === selected.id) ? selected : pictures[0];
        onOpenPictureFax?.(start, pictures, true);
    };

    // FILE OPENING HISTORY
    const openNotepad = (item: FMItem) => {
        const content = item.content ?? '';
        onOpenNotepad?.(content, item.name);
        addRecentDoc({ name: item.name, path: item.id, type: 'txt' });
    };

    const openHtmlPage = (item: FMItem) => {
        if (item.url) { onOpenIE?.(item.url); return; }
        if (item.content) {
            const blobUrl = URL.createObjectURL(new Blob([item.content], { type: 'text/html' }));
            onOpenIE?.(blobUrl);
        }
    };

    const getTrack = (item: FMItem) => item.trackData ?? (item.content ? { name: item.name, url: item.content } : undefined);

    const openWMP = (item: FMItem) => {
        const track = getTrack(item);
        if (!track) return;
        const siblings = sortedChildren.filter(c => getTrack(c));
        const tracks = siblings.map(c => getTrack(c)!);
        const startIndex = siblings.findIndex(c => c.id === item.id);
        onOpenWMP?.(tracks, startIndex);
        addRecentDoc({ name: item.name, path: item.id, type: 'mp3' });
    };

    const renderGridItem = (item: FMItem) => (
        <div
            key={item.id}
            className={`file-grid-item${selectedId === item.id ? ' selected' : ''}`}
            onClick={() => setSelectedId(item.id)}
            onDoubleClick={() => {
                if (pickerMode === 'wallpaper' && item.type !== 'folder') {
                    const url = isPickableImage(item);
                    if (url) { onFilePicked?.(url); return; }
                    // Non-image in picker mode: ignore the double-click
                    return;
                }
                if (pickerMode === 'object' && item.type !== 'folder') {
                    onObjectPicked?.(item);
                    return;
                }
                if (pickerMode === 'audio' && item.type !== 'folder') {
                    if ((item.name.endsWith('.mp3') || item.name.endsWith('.wav') || item.name.endsWith('.webm')) && item.trackData?.url) {
                        onFilePicked?.(item.trackData.url);
                    }
                    return;
                }
                if (item.id === 'cp-fonts') {
                    navigateTo(['localdisc', 'c-windows', 'c-windows-fonts']);
                    return;
                }
                if (item.id === 'cp-display') {
                    onOpenDisplayProperties?.();
                    return;
                }
                if (item.id === 'pfie-iexplore') {
                    onOpenIE?.();
                    return;
                }
                if (item.type === 'folder') {
                    navigateTo([...path, item.id]);
                } else if (item.thumbnailUrl || item.imageUrl) {
                    openPictureFax(item);
                } else if (item.name.endsWith('.lnk')) {
                    onOpenApp(item.id);
                    setSelectedId(null);
                } else if (item.name.endsWith('.txt') || item.name.endsWith('.md')) {
                    openNotepad(item);
                } else if (item.name.endsWith('.html') || item.name.endsWith('.htm')) {
                    openHtmlPage(item);
                } else if (item.url) {
                    onOpenIE?.(item.url);
                }
                else if (item.name.endsWith('.mp3') || item.name.endsWith('.wav') || item.name.endsWith('.webm')) {
                    openWMP(item);
                }
                else if (item.fontUrl) {
                    onOpenFontView?.(item);
                }
            }}
        >
            {viewMode === 'thumbnails' ? (
                <>
                    <div className='file-grid-thumb'>
                        {item.type === 'folder' && item.previewFolder ? (
                            <div className='folder-preview'>
                                {item.children?.filter(c => c.thumbnailUrl).slice(0, 4).map(c => (
                                    <img key={c.id} src={c.thumbnailUrl} alt='' />
                                ))}
                            </div>
                        ) : (
                            <img
                                className={`${item.thumbnailUrl ? 'is-thumbnail' : 'is-icon'}${item.largeThumbnail ? ' large' : ''}`}
                                src={item.thumbnailUrl ?? item.icon}
                                alt=''
                            />
                        )}
                    </div>
                    {editingId === item.id ? (
                        <input
                            autoFocus
                            className='file-rename-input'
                            value={editingName}
                            onChange={e => setEditingName(e.target.value)}
                            onBlur={commitRename}
                            onKeyDown={e => { if (e.key === 'Enter') commitRename(); if (e.key === 'Escape') cancelRename(); }}
                            onClick={e => e.stopPropagation()}
                        />
                    ) : (
                        <span className='file-grid-label'>{item.name}</span>
                    )}
                </>
            ) : viewMode === 'tiles' ? (
                <>
                    <img className='file-grid-icon' src={item.icon} alt='' />
                    <div className='file-grid-info'>
                        {editingId === item.id ? (
                            <input
                                autoFocus
                                className='file-rename-input'
                                value={editingName}
                                onChange={e => setEditingName(e.target.value)}
                                onBlur={commitRename}
                                onKeyDown={e => { if (e.key === 'Enter') commitRename(); if (e.key === 'Escape') cancelRename(); }}
                                onClick={e => e.stopPropagation()}
                            />
                        ) : (
                            <span className='file-grid-label'>{item.name}</span>
                        )}
                        <span className='file-grid-meta'>
                            {item.type === 'folder' ? 'File Folder' : item.size ?? ''}
                        </span>
                    </div>
                </>
            ) : (
                <>
                    <img className='file-grid-icon' src={item.icon} alt='' />
                    {editingId === item.id ? (
                        <input
                            autoFocus
                            className='file-rename-input'
                            value={editingName}
                            onChange={e => setEditingName(e.target.value)}
                            onBlur={commitRename}
                            onKeyDown={e => { if (e.key === 'Enter') commitRename(); if (e.key === 'Escape') cancelRename(); }}
                            onClick={e => e.stopPropagation()}
                        />
                    ) : (
                        <span className='file-grid-label'>{item.name}</span>
                    )}
                </>
            )}
        </div>
    );

    return (
        <div className='file-app'>

            {/* ── Toolbar ── */}
            <div className='file-toolbars'>
                <div className='file-toolbar'>
                    {showStandardButtons && (
                        <div className='file-toolbar-top'>
                            <button
                                type='button'
                                className={`toolbar-btn ${!canGoBack ? 'disabled' : ''}`}
                                onClick={goBack}
                                aria-label='Back'
                            >
                                <img className='toolbar-img' src={Back} alt='Back' />
                                Back
                            </button>
                            <button
                                type='button'
                                className={`toolbar-dropdown-arrow toolbar-btn ${!canGoBack ? 'disabled' : ''}`}
                                onClick={() => {}}
                            >
                                ▾
                            </button>

                            <button
                                type='button'
                                className={`toolbar-btn ${!canGoForward ? 'disabled' : ''}`}
                                onClick={goForward}
                                aria-label='Forward'
                            >
                                <img className='toolbar-img' src={Forward} alt='Forward' />
                            </button>
                            <button
                                type='button'
                                className={`toolbar-dropdown-arrow toolbar-btn ${!canGoForward ? 'disabled' : ''}`}
                                onClick={() => {}}
                            >
                                ▾
                            </button>

                            <button
                                type='button'
                                className={`toolbar-btn ${!canGoUp ? 'disabled' : ''}`}
                                onClick={goUp}
                                aria-label='Up'
                            >
                                <img className='toolbar-img' src={Up} alt='Up' />
                            </button>

                            <div className="border-right"></div>

                            <button
                                type='button'
                                className={`toolbar-btn${showSearch ? ' is-active' : ''}`}
                                aria-label='Search'
                                onClick={onToggleSearch}
                            >
                                <img className='toolbar-img' src={Search} alt='Search' />
                                Search
                            </button>
                            <button type='button' className='toolbar-btn' aria-label='Folders'>
                                <img className='toolbar-img' src={Folders} alt='Folders' />
                                Folders
                            </button>

                            <div className="border-right"></div>

                            {currentNode.id === 'c-windows-fonts' ? (
                                <>
                                    <button type='button' className={`toolbar-btn${viewMode === 'thumbnails' ? ' is-active' : ''}`} onClick={() => onViewChange('thumbnails')}>
                                        <img className='toolbar-img' src={ThumbnailView} alt='Thumbnails' />
                                    </button>
                                    <button type='button' className={`toolbar-btn${viewMode === 'icons' ? ' is-active' : ''}`} onClick={() => onViewChange('icons')}>
                                        <img className='toolbar-img' src={IconView} alt='Large Icons' />
                                    </button>

                                    <button type='button' className={`toolbar-btn${viewMode === 'similarity' ? ' is-active' : ''}`} onClick={() => onViewChange('similarity')}>
                                        <img className='toolbar-img' src={FontSimilarityView} alt='Similarity' />
                                    </button>
                                    <button type='button' className={`toolbar-btn${viewMode === 'details' ? ' is-active' : ''}`} onClick={() => onViewChange('details')}>
                                        <img className='toolbar-img' src={DetailView} alt='Details' />
                                    </button>
                                </>
                            ) : (
                                <div className='file-view-toggle'>
                                    <button
                                        type='button'
                                        className='toolbar-btn'
                                        onClick={() => setViewDropdownOpen(prev => !prev)}
                                    >
                                        <img className='toolbar-img' src={IconView} alt='View' />
                                        ▾
                                    </button>
                                    {viewDropdownOpen && (
                                        <div className='file-view-dropdown'>
                                            <button type='button' className={viewMode === 'thumbnails' ? 'is-active' : ''} onClick={() => { onViewChange('thumbnails'); setViewDropdownOpen(false); }}>
                                                <img src={ThumbnailView} alt='Thumbnails' /> Thumbnails
                                            </button>
                                            <button type='button' className={viewMode === 'tiles' ? 'is-active' : ''} onClick={() => { onViewChange('tiles'); setViewDropdownOpen(false); }}>
                                                <img src={TileView} alt='Tiles' /> Tiles
                                            </button>
                                            <button type='button' className={viewMode === 'icons' ? 'is-active' : ''} onClick={() => { onViewChange('icons'); setViewDropdownOpen(false); }}>
                                                <img src={IconView} alt='Icons' /> Icons
                                            </button>
                                            <button type='button' className={viewMode === 'list' ? 'is-active' : ''} onClick={() => { onViewChange('list'); setViewDropdownOpen(false); }}>
                                                <img src={ListView} alt='List' /> List
                                            </button>
                                            <button type='button' className={viewMode === 'details' ? 'is-active' : ''} onClick={() => { onViewChange('details'); setViewDropdownOpen(false); }}>
                                                <img src={DetailView} alt='Details' /> Details
                                            </button>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                        
                    )}

                    {/* ── Address Bar ── */}
                    {showAddressBar && (
                        <div className='file-toolbar-bottom'>
                            <div className='left'>
                                <span>Address</span>
                                <div className='input-wrapper'>
                                    <img
                                        className='toolbar-img-xs absolute'
                                        src={getFolderIcon(currentNode)}
                                        alt=''
                                    />
                                    <div className='address-bar address-breadcrumbs'>
                                        {breadcrumbs.map((crumb, index) => (
                                            <span key={index} className='address-breadcrumb'>
                                                {index > 0 && <span className='address-separator'>▸</span>}
                                                <button
                                                    type='button'
                                                    className={`address-crumb-btn${index === breadcrumbs.length - 1 ? ' is-current' : ''}`}
                                                    onClick={() => {
                                                        if (index < breadcrumbs.length - 1) navigateTo(path.slice(0, index));
                                                    }}
                                                >
                                                    {crumb.name}
                                                </button>
                                            </span>
                                        ))}
                                    </div>
                                    <button
                                        type='button'
                                        className='more-links'
                                        aria-label='Show history'
                                        onClick={() => {}}
                                    />
                                </div>
                            </div>
                            <div className='right'>
                                <button type='button' className='toolbar-btn' aria-label='Go'>
                                    <img className='toolbar-img-small' src={Go} alt='Go' />
                                    Go
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            <div
                className='file-main'
                onMouseDown={(e) => {
                    const t = e.target as HTMLElement;
                    if (!t.closest('.file-grid-item, .file-list tr, .fm-sidebar')) setSelectedId(null);
                }}
            >
                {showHistory ? (
                    <HistorySidebar
                        navHistory={navHistory}
                        historyIndex={historyIndex}
                        navigateTo={navigateTo}
                        onClose={onCloseHistory}
                    />
                ) : showSearch ? (
                    <SearchSidebar
                        onClose={onCloseSearch}
                        onSearchResults={setSearchResults}
                        globalVolume={globalVolume}
                        globalMuted={globalMuted}
                    />
                ) : (
                    <FileManagerSidebar
                        path={path}
                        navigateTo={navigateTo}
                        currentNode={currentNode}
                        selectedItem={sortedChildren?.find(c => c.id === selectedId) ?? null}
                        showOtherPlaces={showOtherPlaces}
                        apps={apps}
                        controlPanelClassic={controlPanelClassic}
                        onControlPanelClassic={() => setControlPanelClassic(true)}
                        onSwitchToCategory={() => setControlPanelClassic(false)}
                        onStartSlideshow={startSlideshow}
                        onDeleteFile={handleDeleteFile}
                        onRenameFile={handleRenameFile}
                        onNewFolder={handleNewFolder}
                        onRestoreItem={handleRestoreItem}
                        onRestoreAll={handleRestoreAll}
                        onEmptyRecycleBin={handleEmptyRecycleBin}
                        onOpenDisplayProperties={onOpenDisplayProperties}
                        onMoveFile={handleMoveFile}
                        onCopyFile={handleCopyFile}
                    />
                )}
                <XPScrollbar className={`file-content ${viewMode}`}>
                    <div
                        data-folder-type={showSearch ? 'search' : currentNode.folderType}
                        data-cp-classic={controlPanelClassic ? 'true' : undefined}
                        style={{ display: 'contents' }}
                        onClick={(e) => { if (!(e.target as HTMLElement).closest('.file-grid-item, .file-list tr')) setSelectedId(null); }}
                    >
                    {viewMode === 'filmstrip' && sortedChildren.some(c => (c.thumbnailUrl || c.imageUrl) && c.type === 'file') ? (
                        (() => {
                            const pictureItems = sortedChildren.filter(c => (c.thumbnailUrl || c.imageUrl) && c.type === 'file');
                            const activeId = viewerImageId && pictureItems.some(p => p.id === viewerImageId)
                                ? viewerImageId
                                : pictureItems[0].id;
                            return (
                                <PictureViewer
                                    images={pictureItems}
                                    activeId={activeId}
                                    onChange={handleViewerChange}
                                    onOpen={(item) => openPictureFax(item)}
                                />
                            );
                        })()
                    ) : currentNode.id === 'cp-appearance' ? (
                        <ControlPanelAppearance onOpenDisplayProperties={onOpenDisplayProperties} />
                    ) : currentNode.id === 'cp-network' ? (
                        <ControlPanelNetwork />
                    ) : currentNode.id === 'cp-printers' ? (
                        <ControlPanelPrinters />
                    ) : currentNode.id === 'cp-date' ? (
                        <ControlPanelDate />
                    ) : currentNode.id === 'cp-accessibility' ? (
                        <ControlPanelAccessibility />
                    ) : currentNode.id === 'cp-users' ? (
                        <ControlPanelAccounts />
                    ) : currentNode.id === 'cp-audio' ? (
                        <ControlPanelSound onOpenVolumeControl={onOpenVolumeControl} />
                    ) : currentNode.id === 'cp-performance' ? (
                        <ControlPanelPerformance />
                    ) : currentNode.id === 'controlpanel' && !controlPanelClassic ? (
                        <ControlPanelHome navigateTo={navigateTo} path={path} />
                    ) : currentNode.id === 'c-windows-fonts' && viewMode === 'similarity' ? (
                        <>
                            <div className='font-similarity-bar'>
                                <span>List fonts by similarity to:</span>
                                <select
                                    value={similarityBaseFont}
                                    onChange={e => setSimilarityBaseFont(e.target.value)}
                                >
                                    {sortedChildren.filter(c => c.fontUrl).map(c => (
                                        <option key={c.id} value={c.displayName ?? c.name}>
                                            {c.displayName ?? c.name}
                                        </option>
                                    ))}
                                </select>
                            </div>
                            <table className='file-list similarity-list'>
                                <thead>
                                    <tr>
                                        <th>Name</th>
                                        <th>Similarity to {similarityBaseFont}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {sortedChildren.map(item => (
                                        <tr
                                            key={item.id}
                                            className={selectedId === item.id ? 'selected' : ''}
                                            onClick={() => setSelectedId(item.id)}
                                            onDoubleClick={() => { if (item.fontUrl) onOpenFontView?.(item); }}
                                        >
                                            <td className='file-list-name'>
                                                <img src={item.icon ?? ''} alt='' className='file-list-icon' />
                                                {item.displayName ?? item.name}
                                            </td>
                                            <td className={`similarity-cell similarity-${item.similarity ?? 'not-similar'}`}>
                                                {item.similarity === 'very-similar'
                                                    ? 'Very similar'
                                                    : item.similarity === 'fairly-similar'
                                                        ? 'Fairly similar'
                                                        : 'Not similar'}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </>
                    ) : currentNode.hidden && !revealedHidden.has(currentNode.id) ? (
                        <HiddenFolderWarning onReveal={() => setRevealedHidden(prev => new Set(prev).add(currentNode.id))} />
                    ) : sortedChildren && sortedChildren.length > 0 ? (
                        viewMode === 'details' ? (
                            <table className='file-list'>
                                <thead>
                                    <tr>
                                        <th>Name</th>
                                        <th>Size</th>
                                        <th>Type</th>
                                        <th>Date Modified</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {(rootGroups
                                        ? [
                                            ...rootGroups.groups.flatMap(g => [{ __header: g.category } as const, ...g.items]),
                                            ...rootGroups.uncategorized,
                                        ]
                                        : sortedChildren
                                    ).map((row: FMItem | { __header: string }) => '__header' in row ? (
                                        <tr key={`hdr-${row.__header}`}>
                                            <td colSpan={4}>
                                                <div className='fm-category-header'>{row.__header}</div>
                                            </td>
                                        </tr>
                                    ) : ((item: FMItem) => (
                                        <tr
                                            key={item.id}
                                            className={selectedId === item.id ? 'selected' : ''}
                                            onClick={() => setSelectedId(item.id)}
                                            onDoubleClick={() => {
                                                if (pickerMode === 'wallpaper' && item.type !== 'folder') {
                                                    const url = isPickableImage(item);
                                                    if (url) { onFilePicked?.(url); return; }
                                                    // Non-image in picker mode: ignore the double-click
                                                    return;
                                                }
                                                if (pickerMode === 'object' && item.type !== 'folder') {
                                                    onObjectPicked?.(item);
                                                    return;
                                                }
                                                if (pickerMode === 'audio' && item.type !== 'folder') {
                                                    if ((item.name.endsWith('.mp3') || item.name.endsWith('.wav') || item.name.endsWith('.webm')) && item.trackData?.url) {
                                                        onFilePicked?.(item.trackData.url);
                                                    }
                                                    return;
                                                }
                                                if (item.id === 'cp-fonts') {
                                                    navigateTo(['localdisc', 'c-windows', 'c-windows-fonts']);
                                                    return;
                                                }
                                                if (item.id === 'cp-display') {
                                                    onOpenDisplayProperties?.();
                                                    return;
                                                }
                                                if (item.id === 'pfie-iexplore') {
                                                    onOpenIE?.();
                                                    return;
                                                }
                                                else if (item.type === 'folder') {
                                                    navigateTo([...path, item.id]);
                                                } else if (item.thumbnailUrl || item.imageUrl) {
                                                    openPictureFax(item);
                                                } else if (item.name.endsWith('.lnk')) {
                                                    onOpenApp(item.id);
                                                    setSelectedId(null);
                                                }
                                                else if (item.name.endsWith('.txt') || item.name.endsWith('.md')) {  
                                                    openNotepad(item);
                                                } else if (item.name.endsWith('.html') || item.name.endsWith('.htm')) {
                                                    openHtmlPage(item);
                                                } else if (item.url) {
                                                    onOpenIE?.(item.url);
                                                }
                                                else if (item.name.endsWith('.mp3') || item.name.endsWith('.wav') || item.name.endsWith('.webm')) {
                                                    openWMP(item);
                                                } else if (item.fontUrl) {
                                                    onOpenFontView?.(item);
                                                }
                                            }}
                                        >
                                            <td className='file-list-name'>
                                                <img src={item.icon ?? ''} alt='' className='file-list-icon' />
                                                {editingId === item.id ? (
                                                    <input
                                                        autoFocus
                                                        className='file-rename-input'
                                                        value={editingName}
                                                        onChange={e => setEditingName(e.target.value)}
                                                        onBlur={commitRename}
                                                        onKeyDown={e => {
                                                            if (e.key === 'Enter') commitRename();
                                                            if (e.key === 'Escape') cancelRename();
                                                        }}
                                                        onClick={e => e.stopPropagation()}
                                                    />
                                                ) : item.name}
                                            </td>
                                            <td>{item.size ?? ''}</td>
                                            <td>
                                                {item.type === 'folder'
                                                    ? 'File Folder'
                                                    : item.name.endsWith('.lnk')
                                                        ? 'Shortcut'
                                                        : 'File'}
                                            </td>

                                            <td>{item.modified ?? ''}</td>
                                        </tr>
                                    ))(row))}
                                </tbody>
                            </table>
                        ) : rootGroups ? (
                            <>
                                {rootGroups.groups.map(({ category, items }) => (
                                    <div key={category} className='fm-category-group'>
                                        <div className='fm-category-header'>{category}</div>
                                        <div className='fm-category-items'>
                                            {items.map(item => renderGridItem(item))}
                                        </div>
                                    </div>
                                ))}
                                {rootGroups.uncategorized.length > 0 && (
                                    <div className='fm-category-group'>
                                        <div className='fm-category-items'>
                                            {rootGroups.uncategorized.map(item => renderGridItem(item))}
                                        </div>
                                    </div>
                                )}
                            </>
                        ) : (
                            sortedChildren.map(item => renderGridItem(item))
                        )
                    ) : (
                        <div className='file-empty'>This folder is empty.</div>
                    )}
                </div></XPScrollbar>
            </div>

            {/* tip of the day */}
            {showTipOfTheDay && (
                <TipOfTheDay onClose={onCloseTipOfTheDay} />
            )}

            {/* status bar */}
            {showStatusBar && (
                <div className='file-status-bar'>
                    <span className='file-status-count'>
                        {sortedChildren?.length ?? 0} object{(sortedChildren?.length ?? 0) !== 1 ? 's' : ''}
                    </span>
                    <span className='file-status-path'>
                        {breadcrumbs.map(c => c.name).join(' \\ ')}
                    </span>
                    {pickerMode === 'object' && selectedId && (() => {
                        const item = sortedChildren?.find(c => c.id === selectedId);
                        return item && item.type !== 'folder'
                            ? <button className='luna-btn' style={{ marginLeft: 'auto' }} onClick={() => onObjectPicked?.(item)}>Open</button>
                            : null;
                    })()}
                </div>
            )}

            {pendingDelete && createPortal(
                <CriticalError
                    type='confirmDelete'
                    messageOverride={[
                        currentNode.id === 'recyclebin'
                            ? `Are you sure you want to permanently delete '${pendingDelete.name}'?`
                            : `Are you sure you want to send '${pendingDelete.name}' to the Recycle Bin?`
                    ]}
                    onClose={() => setPendingDelete(null)}
                    onYes={confirmDelete}
                    onNo={() => setPendingDelete(null)}
                    onCancel={() => setPendingDelete(null)}
                />,
                document.body
            )}

            {moveCopyTarget && createPortal(
                <MoveCopyDialog
                    mode={moveCopyTarget.mode}
                    item={moveCopyTarget.item}
                    currentParentId={currentNode.id}
                    onConfirm={confirmMoveCopy}
                    onClose={() => setMoveCopyTarget(null)}
                    getExtraChildren={getExtraChildren}
                    isDeleted={isDeleted}
                    onNewFolder={(parentId) => {
                        const findNode = (node: FMItem, id: string): FMItem | null => {
                            if (node.id === id) return node;
                            for (const child of [...(node.children ?? []), ...getExtraChildren(node.id)]) {
                                const found = findNode(child, id);
                                if (found) return found;
                            }
                            return null;
                        };
                        const targetNode = findNode(FILE_SYSTEM, parentId);
                        const existingNames = new Set([
                            ...(targetNode?.children ?? []),
                            ...getExtraChildren(parentId),
                        ]
                            .filter(c => !isDeleted(c.id))
                            .map(c => c.name));

                        let name = 'New Folder';
                        if (existingNames.has(name)) {
                            let n = 1;
                            while (existingNames.has(`New Folder (${n})`)) n++;
                            name = `New Folder (${n})`;
                        }

                        createFile(parentId, {
                            id: generateId('folder'),
                            type: 'folder',
                            name,
                            icon: FolderClosedIcon,
                            children: [],
                        });
                    }}
                />,
                document.body
            )}
        </div>
    );
}

export default FileManagerApp
